package com.propverse.service;
import com.propverse.database.DBConnection;import com.propverse.util.PasswordUtil;import java.sql.*;
public class AuthenticationService {public boolean login(String u,char[] pw)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT password_hash FROM users WHERE username=?")){p.setString(1,u);try(ResultSet r=p.executeQuery()){return r.next()&&PasswordUtil.verify(pw,r.getString(1));}}}public void createAdmin(String u,char[] pw)throws SQLException{if(u==null||u.isBlank()||pw.length<10)throw new IllegalArgumentException("Username required and password must contain at least 10 characters.");try(Connection c=DBConnection.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT COUNT(*) FROM users")){r.next();if(r.getInt(1)>0)throw new IllegalStateException("An account already exists.");}try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO users(username,password_hash,role) VALUES(?,?,'ADMIN')")){p.setString(1,u.trim());p.setString(2,PasswordUtil.hash(pw));p.executeUpdate();}}}
